  function units(value,multiplier){if(String(value).trim()==='')return null;if(!/^\d+(?:\.\d{0,6})?$/.test(String(value)))throw Error('Enter a non-negative number with no more than six decimal places.');const n=Number(value)*multiplier;if(!Number.isSafeInteger(Math.round(n))||Math.abs(n-Math.round(n))>=0.00001)throw Error('Use a time or distance that resolves to whole milliseconds or millimetres.');return Math.round(n);}
  function decimal(value,scale){return value===null||value===undefined?'':String(Number((value/scale).toFixed(6)));}
  function editedUnits(value,multiplier,original){if(Number.isSafeInteger(original)&&original>=0&&String(value)===decimal(original,multiplier))return original;return units(value,multiplier);}
