  function planned(p){const v=p.value||p;if(v.type==='sequence'){const work=v.segments.filter(x=>x.kind==='work'),rest=v.segments.filter(x=>x.kind==='rest'),known=v.segments.every(x=>x.targetDurationMs!==null);return work.length+' work · '+rest.length+' rest'+(known?' · '+duration(v.segments.reduce((n,x)=>n+x.targetDurationMs,0))+' planned':' · distance-led timing');}return [v.targetDurationMs!==null?duration(v.targetDurationMs):null,v.targetDistanceMm!==null?distance(v.targetDistanceMm):null].filter(Boolean).join(' · ');}
  function activityName(v){if(v.type==='sequence')return 'Intervals';return modes.find(x=>x[0]===v.activity)?.[1]||v.activity;}
  function contextLabel(p){const v=p.value||p,e=p.equipment;return [v.location,v.surface,(Array.isArray(e)?[...new Set(e.map(x=>x?.equipment?.value?.name||x?.value?.name).filter(Boolean))].join(', '):e?.value?.name),v.load!==null&&v.load!==undefined?v.load+' '+(conventions.find(x=>x[0]===v.convention)?.[1]||v.convention):null].filter(Boolean).join(' · ');}
  function show(title,html){api.dialog(title,'<div class="conditioning-dialog">'+html+'</div>');}
