  function prescriptionEditor(e,f){const report=ctx().workspace.domains.athletics.restrictions.find(x=>x.id===e.restrictionVersionId),list=equipment(),old=ctx().workspace.domains.athletics.equipment.find(x=>x.id===e.equipmentVersionId);if(old&&!list.some(x=>x.id===old.id))list.push(old);const eq=list.find(x=>x.id===e.equipmentVersionId);return '<p class="conditioning-help">'+esc(activityName(e))+'. '+(e.type==='hold'?'Enter seconds held.':'Enter time, distance, or both.')+' Existing targets are copied only from your own earlier approved activity.</p>'+input('title','Activity title',e.title,'maxlength="120" required')+'<div class="conditioning-form-grid">'+input('date','Planned date',e.date,'type="date" required')+input('duration',e.type==='hold'?'Target hold, seconds':'Target work, minutes',f.duration,'type="number" min="0" step="any" inputmode="decimal" '+(e.type==='hold'?'required':''))+(e.type==='locomotion'?input('distance','Target distance, km',f.distance,'type="number" min="0" step="any" inputmode="decimal" placeholder="Leave unknown if time only"'):'')+input('variant','Activity or movement variant',e.variant,'maxlength="80" required')+input('location','Location / setting',e.location,'maxlength="80" required')+select('equipmentVersionId','Equipment or machine',e.equipmentVersionId||'',[['','No equipment / outdoors'],...list.map(x=>[x.id,x.value.name+' · '+x.value.location+(equipment().some(y=>y.id===x.id)?'':' · earlier version')])])+(e.activity==='carry'?input('load','External load, '+esc(conventions.find(x=>x[0]===eq?.value.convention)?.[1]||'choose equipment first'),e.load??'','type="number" min="0" max="2000" step="any" inputmode="decimal" required'):'')+'</div><div class="conditioning-report"><strong>Current report attached</strong><p>'+esc(report?.value.note||'No movement patterns marked to avoid in the saved report.')+'</p>'+(latestReport()?.id!==e.restrictionVersionId?button('current-report','Use my current report','','text-button'):'')+'</div><details><summary>Context and development focus</summary><div class="conditioning-form-grid">'+input('timeZone','Time zone',e.timeZone,'maxlength="100" required')+input('surface','Surface / conditions, optional',e.surface,'maxlength="80"')+select('phase','Session phase',e.phase,[['work','Work'],['warmup','Warm-up'],['cooldown','Cool-down']])+'</div><p class="conditioning-help">Focus is an intention. Select the movement patterns involved so the saved restriction report can be checked.</p>'+checks('focus',e.focus,capabilities)+checks('pattern',e.patterns,patterns)+textarea('note','Plan notes, optional',e.note)+'</details>';}
  function actualEditor(e,f,kind){const result=current(e.sessionId),s=result.session;if(!s)return '<p class="conditioning-warning">The original session is missing.</p>';const hold=s.prescription.value.type==='hold',observed=service().elapsed(s,stamp()),original=s.history.find(x=>x.operation==='finish')?.actual;return '<div class="conditioning-target"><small>Original target</small><strong>'+esc(planned(s.prescription))+'</strong><span>'+esc(s.prescription.value.title)+'</span></div><p class="conditioning-help">'+(kind==='correct'?'This appends a correction. The original record remains readable.':'The session stays paused while you review what happened.')+'</p>'+select('outcome','How did it finish?',e.outcome,[['complete','Finished as intended'],['incomplete','Stopped early / incomplete']])+select('durationSource','Where does the actual duration come from?',e.actual.durationSource,[...(kind!=='correct'||original?.durationSource==='timer'?[['timer','Use the saved session timer']]:[]),['entered','I have a measured duration to enter'],['estimated','My estimate'],['unknown','Duration not known']])+(e.actual.durationSource==='timer'?'<div class="conditioning-timer-review"><strong>'+esc(duration(kind==='correct'?original?.durationMs:observed.elapsedMs))+'</strong><label><input type="checkbox" data-conditioning-confirmed '+(e.timingConfirmed?'checked':'')+'>This timer matches my work, excluding breaks.</label><p class="conditioning-help">Check for device clock changes or time left running. Choose an entered duration or estimate if this does not match.</p></div>':['entered','estimated'].includes(e.actual.durationSource)?input('duration',hold?'Actual hold, seconds':'Actual work, minutes',f.duration,'type="number" min="0" step="any" inputmode="decimal" required'):'')+(!hold?'<div class="conditioning-form-grid">'+input('distance','Actual distance, km',f.distance,'type="number" min="0" step="any" inputmode="decimal" placeholder="Unknown, leave blank"')+select('distanceSource','Distance source',e.actual.distanceSource,[['unknown','Unknown'],['measured','Measured during the activity'],['entered','Entered from another record'],['estimated','My estimate']])+'</div>':'')+select('effort','How hard did it feel?',e.actual.effort,[['unknown','Not recorded'],['easy','Easy'],['moderate','Moderate'],['hard','Hard']])+textarea('discomfort','Discomfort or limitations, optional',e.actual.discomfort)+textarea('note','What happened, optional',e.actual.note)+(s.latestVersionId!==draft.data.previousVersionId?'<p class="conditioning-warning">The session changed since this draft began. Review its current state before saving.</p>'+button('refresh-actual','Use the current paused session','','text-button'):'');}
  function renderEditor(){return contextual(()=>{if(!draft)return;review=null;const d=draft.data,body=draft.kind==='prescribe-sequence'?sequenceEditor(d.entity,d.form):['advance','correct-segment'].includes(draft.kind)?segmentEditor(d.entity,d.form,draft.kind):draft.kind==='finish-sequence'?sequenceFinishEditor(d.entity):['observe','correct-observation'].includes(draft.kind)?observationEditor(d.entity,d.form,draft.kind):draft.kind==='prescribe'?prescriptionEditor(d.entity,d.form):actualEditor(d.entity,d.form,draft.kind);show(draft.kind==='prescribe-sequence'?'Build your interval session.':draft.kind==='prescribe'?'Make the activity specific.':draft.kind==='advance'?'Finish this interval.':draft.kind==='finish-sequence'?'Finish the interval session.':draft.kind==='correct'||draft.kind==='correct-segment'||draft.kind==='correct-observation'?'Correct the actual record.':draft.kind==='observe'?'Record the activity.':'What did you actually do?','<form id="conditioningEditorForm">'+body+errorHtml()+'<div class="dialog-footer">'+button('close-draft','Close for now')+'<button class="button primary" type="submit">Review '+(draft.kind==='prescribe-sequence'?'sequence':draft.kind==='prescribe'?'activity':draft.kind==='advance'?'this interval':'actual record')+'</button></div></form>');});}
  function fields(node){const out={};node?.querySelectorAll('[data-conditioning-field]').forEach(x=>{out[x.dataset.conditioningField]=x.value;});return out;}
  function sync(){const form=$('conditioningEditorForm');if(!form||!draft||busy||review)return;const e=draft.data.entity,f=fields(form);if(!['prescribe','finish','correct'].includes(draft.kind)){syncExtended(form,f);return;}for(const key of ['duration','distance'])if(f[key]!==undefined)draft.data.form[key]=f[key];if(draft.kind==='prescribe'){for(const key of ['title','date','timeZone','variant','location','phase','surface','note'])if(f[key]!==undefined)e[key]=f[key];if(f.equipmentVersionId!==undefined)e.equipmentVersionId=f.equipmentVersionId||null;if(e.equipmentVersionId&&!e.location){const selected=ctx().workspace.domains.athletics.equipment.find(x=>x.id===e.equipmentVersionId);if(selected)e.location=selected.value.location;}e.focus=[...form.querySelectorAll('[data-conditioning-focus]:checked')].map(x=>x.dataset.conditioningFocus);e.patterns=[...form.querySelectorAll('[data-conditioning-pattern]:checked')].map(x=>x.dataset.conditioningPattern);if(e.activity==='carry'){if(f.load!==undefined)e.load=f.load;const eq=ctx().workspace.domains.athletics.equipment.find(x=>x.id===e.equipmentVersionId);e.convention=eq?.value.convention||null;}else{e.load=null;e.convention=null;}}else{for(const key of ['durationSource','distanceSource','effort','discomfort','note'])if(f[key]!==undefined)e.actual[key]=f[key];e.outcome=f.outcome??e.outcome;const confirmation=form.querySelectorAll('[data-conditioning-confirmed]')[0];e.timingConfirmed=!!confirmation?.checked;}}
  function normalized(){if(!['prescribe','finish','correct'].includes(draft.kind))return normalizedExtended();const e=copy(draft.data.entity),f=draft.data.form;if(draft.kind==='prescribe'){e.targetDurationMs=editedUnits(f.duration,e.type==='hold'?1000:60000,e.targetDurationMs);e.targetDistanceMm=e.type==='hold'?null:editedUnits(f.distance,1000000,e.targetDistanceMm);if(e.activity==='carry')e.load=e.load===''?NaN:Number(e.load);}else{const hold=current(e.sessionId).session?.prescription.value.type==='hold';e.actual.durationMs=['entered','estimated'].includes(e.actual.durationSource)?editedUnits(f.duration,hold?1000:60000,e.actual.durationMs):null;e.actual.distanceMm=hold?null:editedUnits(f.distance,1000000,e.actual.distanceMm);if(hold)e.actual.distanceSource='unknown';if(e.actual.durationSource!=='timer')e.timingConfirmed=false;}return e;}
  function newCommand(operation,entity,meta){return {contract:'lifeos-conditioning/1',operation,operationId:meta.operationId,versionId:meta.versionId,recordedAt:domain().operations?.find(x=>x.id===meta.operationId)?.command.recordedAt||stamp(),expected:{workspaceRevision:ctx().revision,previousVersionId:meta.previousVersionId||null},entity:copy(entity)};}
  async function prepareReview(){if(busy||!draft)return;sync();keepNow();const identity=draft,token=generation;busy=true;try{const saved=await api.flush();if(saved?.ok===false)throw Error(saved.error||'Earlier changes were not saved.');if(identity!==draft||token!==generation)return;const c=ctx(),command=newCommand(draft.kind,normalized(),draft.data),prepared=service().prepare(command,c);if(!prepared.ok)throw Error(prepared.error||'Check this activity before saving.');review={...prepared,command:prepared.command||command};renderReview();}catch(e){if(identity===draft&&token===generation)error(e.message+' Your edit is retained.');}finally{busy=false;}}
  function renderReview(){return contextual(()=>{if(!review)return;const command=review.command,e=command.entity;let body;if(['prescribe-sequence','advance','skip','correct-segment','finish-sequence','observe','correct-observation'].includes(command.operation))return renderExtendedReview();if(command.operation==='prescribe')body='<h3>'+esc(e.title)+'</h3><p class="conditioning-context">'+esc(labelDate(e.date))+' · '+esc(e.location)+' · '+esc(e.timeZone)+'</p><div class="conditioning-target"><small>Planned '+esc(e.phase)+'</small><strong>'+esc(planned(e))+'</strong><span>'+esc(e.variant)+'</span></div><p class="conditioning-help">'+(e.load!==null?'External load: '+esc(e.load)+' '+esc(conventions.find(x=>x[0]===e.convention)?.[1]||e.convention)+'. ':'')+'Your targets, equipment and current report will be kept with this session.</p>';else if(command.operation==='start'){const p=domain().prescriptions.find(x=>x.id===e.binding.prescriptionId);body='<h3>'+esc(p?.value.title)+'</h3><div class="conditioning-target"><small>Exact approved target</small><strong>'+esc(p?planned(p):'Missing plan')+'</strong></div><p class="conditioning-help">Starts a timer for this activity only. Actual results are reviewed when you finish.</p>';}else if(command.operation==='discard')body='<p class="conditioning-warning">Discard this session without an actual result. The start and discard remain in history.</p>';else{const result=current(e.sessionId),s=result.session,a=review.record?.actual||review.record?.value?.actual||e.actual,timerValue=command.operation==='correct'?s?.actual?.durationMs:service().elapsed(s,command.recordedAt).elapsedMs;body='<h3>'+esc(s?.prescription.value.title)+'</h3><div class="conditioning-comparison"><div><small>Planned</small><strong>'+esc(s?planned(s.prescription):'Missing plan')+'</strong></div><div><small>'+esc(e.outcome==='incomplete'?'Actual · incomplete':'Actual')+'</small><strong>'+esc(duration(a.durationSource==='timer'&&a.durationMs===null?timerValue:a.durationMs))+'</strong><span>'+esc(distance(a.distanceMm))+'</span></div></div><p class="conditioning-help">Time: '+esc(e.actual.durationSource)+'. Distance: '+esc(e.actual.distanceSource)+'. Effort: '+esc(e.actual.effort)+'.</p>'+(e.actual.discomfort?'<p class="conditioning-warning">'+esc(e.actual.discomfort)+'</p>':'')+'<p class="conditioning-note">'+esc(e.actual.note)+'</p>';}show(command.operation==='start'?'Start this exact activity?':'Review before saving.','<div class="conditioning-review"><div class="eyebrow">Review · nothing committed</div>'+body+(review.warnings||[]).filter(x=>!(command.operation==='prescribe'&&typeof x==='string'&&x.startsWith('This is a manual activity plan'))).map(x=>'<p class="conditioning-warning">'+esc(typeof x==='string'?x:x.message||JSON.stringify(x))+'</p>').join('')+errorHtml()+'<div class="dialog-footer">'+button(draft?'resume-draft':'close','Back')+button('commit',command.operation==='prescribe'?'Approve activity':command.operation==='start'?'Start activity':command.operation==='discard'?'Discard without an actual':'Save actual record','','button primary')+'</div></div>');});}
  async function commitReview(){
    if(busy||!review)return;let chosen=review;const identity=draft,token=generation;busy=true;
    try{
      const edge=chosen.command.operation==='start'||chosen.command.operation==='advance'&&chosen.command.entity.nextState==='running'||chosen.command.operation==='skip'&&chosen.command.entity.nextState==='running';
      if(edge&&!chosen.attempted){
        const flushed=await api.flush();if(flushed?.ok===false)throw Error(flushed.error||'Earlier changes were not saved.');
        const context=ctx(),checked=service().prepare(copy(chosen.command),context);if(!checked.ok)throw Error(checked.error||'Review the current session before starting.');
        if(checked.status!=='already-committed'){
          if(checked.reviewDigest!==chosen.reviewDigest)throw Error('The activity changed. Review its current details before starting.');
          const command=copy(chosen.command);command.recordedAt=stamp();const refreshed=service().prepare(command,context);if(!refreshed.ok)throw Error(refreshed.error||'Review the activity for the current time.');
          chosen=review={...refreshed,command:refreshed.command||command,attempted:true};
          if(pending){pending.command=copy(chosen.command);pending.attempted=true;}
        }
      }
      const result=await api.commit(copy(chosen.command),chosen.reviewDigest,{clearDraft:!!draft});if(result?.ok===false)throw Error(result.error||'This activity was not saved.');
      if(identity===draft||draft===null){draft=null;review=null;pending=null;generation++;if(saveTimer){clearTimeout(saveTimer);saveTimer=null;}api.closeDialog();if(chosen.command.operation==='start')api.navigate('train');else api.render();api.toast(chosen.command.operation==='start'?'Activity started on this device.':['prescribe','prescribe-sequence'].includes(chosen.command.operation)?'Activity approved on this device.':'Movement record saved on this device.');}
    }catch(e){if((draft===identity&&token===generation)||review===chosen){error(e.message+' Review again if the records changed.');$('conditioningError')?.insertAdjacentHTML('afterend',button(draft?'review':'review-pending','Review again','','text-button'));}}
    finally{busy=false;}
  }
  async function preparePending(){if(busy||!pending)return;busy=true;const intent=pending;try{const saved=await api.flush();if(saved?.ok===false)throw Error(saved.error||'Earlier changes were not saved.');if(intent!==pending)return;const c=ctx(),command=copy(intent.command||newCommand(intent.operation,intent.entity,intent));command.expected.workspaceRevision=c.revision;const prepared=service().prepare(command,c);if(!prepared.ok)throw Error(prepared.error||'This activity needs review.');intent.command=command;review={...prepared,command:prepared.command||command,attempted:!!intent.attempted};renderReview();}catch(e){show('This activity needs review.','<p class="conditioning-warning">'+esc(e.message)+'</p>'+button('close','Close')+button('review-pending','Review again','','button primary'));}finally{busy=false;}}
  async function openStart(binding,plannerDate=null,plannerSlotId=null){if(busy||!available())return false;pending={operation:'start',operationId:uid('condop'),versionId:uid('condv'),previousVersionId:null,entity:{binding:copy(binding),sessionId:uid('movement'),plannerDate,plannerSlotId}};await preparePending();return !!review;}
  async function direct(operation,sessionId,after){if(busy)return false;const s=current(sessionId).session;if(!s){api.toast('The active movement session could not be found.');return false;}const intent={operation,operationId:uid('condop'),versionId:uid('condv'),previousVersionId:s.latestVersionId,entity:{sessionId,note:''},after};pending=intent;return runDirect();}
  async function runDirect(){if(busy||!pending)return false;const intent=pending;busy=true;try{const saved=await api.flush();if(saved?.ok===false)throw Error(saved.error||'Earlier changes were not saved.');const c=ctx(),command=copy(intent.command||newCommand(intent.operation,intent.entity,intent));command.expected.workspaceRevision=c.revision;intent.command=command;const prepared=service().prepare(command,c);if(!prepared.ok)throw Error(prepared.error||'This timer change needs review.');const result=await api.commit(command,prepared.reviewDigest,{clearDraft:false});if(result?.ok===false)throw Error(result.error||'This timer change was not saved.');pending=null;api.closeDialog();api.render();busy=false;if(intent.after)intent.after();return true;}catch(e){show('The timer change was not confirmed.','<p class="conditioning-warning">'+esc(e.message)+'</p><p class="conditioning-help">The last durable state is retained. Retry this same action to check whether it was saved.</p>'+button('retry-direct','Retry the same action','','button primary')+button('close','Close'));return false;}finally{busy=false;}}
  function finishDraft(sessionId,kind='finish'){const s=current(sessionId).session;if(!s)return;const a=kind==='correct'?copy(s.actual):{durationMs:null,durationSource:'timer',distanceMm:null,distanceSource:'unknown',effort:'unknown',discomfort:'',note:''};if(!a)return api.toast('This session has no finished actual to correct.');keep(kind,{sessionId,outcome:kind==='correct'?(s.event?.outcome||s.event?.value?.outcome||'complete'):'complete',actual:a,timingConfirmed:false},s.latestVersionId,{duration:decimal(a.durationMs,s.prescription.value.type==='hold'?1000:60000),distance:decimal(a.distanceMm,1000000)});renderEditor();}
  async function finish(sessionId){if(!available()||busy)return;const s=current(sessionId).session;if(!s)return;if(s.status==='running')await direct('pause',sessionId,()=>finishDraft(sessionId));else if(s.status==='paused')finishDraft(sessionId);}
  function sourceDetail(sessionId,versionId=null){
    const result=current(sessionId),s=result.session;if(!result.ok||!s){api.toast(result.error||'This source record could not be found.');return false;}
    if(s.sequence)return sequenceSourceDetail(sessionId,versionId);
    const selected=versionId?s.history.find(e=>e.id===versionId&&['finish','correct'].includes(e.operation)):s.event;
    if(versionId&&!selected){api.toast('That exact actual version could not be found.');return false;}
    const a=selected?.actual||s.actual,earlier=selected&&selected.id!==s.latestVersionId;
    show('The source actual.','<div class="conditioning-source" data-conditioning-source-version="'+esc(selected?.id||'')+'"><div class="eyebrow">'+(earlier?'Earlier actual':'Current actual')+'</div><h3>'+esc(s.prescription.value.title)+'</h3><p class="conditioning-context">'+esc(labelDate(s.date))+' · '+esc(contextLabel(s.prescription))+'</p>'+(earlier?'<p class="conditioning-warning">This is the earlier actual linked to this source. A later correction exists.</p>':'')+(a?'<div class="conditioning-comparison"><div><small>Planned</small><strong>'+esc(planned(s.prescription))+'</strong></div><div><small>'+esc(earlier?'Earlier actual':'Current actual')+' · '+esc(selected?.value?.outcome==='incomplete'?'Incomplete':'Finished')+'</small><strong>'+esc(duration(a.durationMs))+'</strong><span>'+esc(distance(a.distanceMm))+'</span></div></div><p class="conditioning-help">Time source: '+esc(a.durationSource)+'. Distance source: '+esc(a.distanceSource)+'. Effort: '+esc(a.effort)+'.</p><p class="conditioning-note">'+esc(a.discomfort)+'<br>'+esc(a.note)+'</p>':'')+'<details class="conditioning-history" open><summary>Immutable session history · '+s.history.length+'</summary>'+s.history.map(e=>'<div><strong>'+esc(e.operation)+'</strong><span>'+esc(e.recordedAt)+'</span>'+(e.actual?'<small>'+esc(duration(e.actual.durationMs))+' · '+esc(distance(e.actual.distanceMm))+'</small>'+button('version','Open this version','data-version="'+esc(e.id)+'"','text-button'):'')+'</div>').join('')+'</details>'+(a?button('correct','Correct the current actual','data-session="'+esc(sessionId)+'"','button primary'):'')+button('close','Close')+'</div>');return true;
  }
  function openActual(versionId){if(!api)return false;return contextual(()=>{const event=domain().events.find(x=>x.id===versionId&&['finish','correct','finish-sequence','advance','correct-segment'].includes(x.operation));if(!event){api.toast('That exact actual version could not be found.');return false;}return sourceDetail(event.sessionId,versionId);});}
  function buildSequence(id){
    if(!available())return;const report=latestReport();if(!report){show('Record your current limits first.','<p class="conditioning-help">Your report stays attached to the session you approve.</p>'+button('limits','Record my current limits','','button primary'));return;}
    const source=domain().prescriptions.find(x=>x.id===id&&x.value.type==='sequence')?.value,zone=source?.timeZone||Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';
    const entity=source?{...copy(source),date:localDay(zone),restrictionVersionId:report.id,segments:source.segments.map(x=>({...copy(x),segmentId:uid('segment')}))}:{type:'sequence',title:'Interval session',date:localDay(zone),timeZone:zone,location:'',focus:['conditioning'],restrictionVersionId:report.id,note:'',segments:[]};
    const first=entity.segments.find(x=>x.kind==='work');keep('prescribe-sequence',entity,null,{activity:first?.activity||'run',workDuration:'',workDistance:'',restDuration:'',rounds:'',segments:entity.segments.map(x=>({segmentId:x.segmentId,duration:decimal(x.targetDurationMs,1000),distance:x.kind==='work'?decimal(x.targetDistanceMm,1000):''}))});renderEditor();
  }
  function repeatSequence(){
    if(draft?.kind!=='prescribe-sequence')return;sync();const e=draft.data.entity,f=draft.data.form,mode=modes.find(x=>x[0]===f.activity);try{
      const rounds=Number(f.rounds),workMs=units(f.workDuration,1000),workMm=mode[2]==='hold'?null:units(f.workDistance,1000),restMs=units(f.restDuration,1000);
      if(!Number.isSafeInteger(rounds)||rounds<1||rounds>50)throw Error('Choose 1 to 50 rounds.');if(!(workMs>0||workMm>0)||mode[2]==='hold'&&!(workMs>0))throw Error('Enter the work target before building the sequence.');if(rounds>1&&!(restMs>0))throw Error('Enter rest seconds between rounds.');
      const prior=e.segments.find(x=>x.kind==='work'&&x.activity===mode[0]);e.segments=[];f.segments=[];
      for(let n=0;n<rounds;n++){const work=prior?{...copy(prior),segmentId:uid('segment'),label:mode[1]+' '+(n+1),targetDurationMs:workMs,targetDistanceMm:workMm}:{segmentId:uid('segment'),kind:'work',label:mode[1]+' '+(n+1),type:mode[2],activity:mode[0],variant:mode[4],patterns:[mode[5]],phase:'work',equipmentVersionId:null,load:null,convention:null,targetDurationMs:workMs,targetDistanceMm:workMm,surface:'',note:''};e.segments.push(work);f.segments.push({segmentId:work.segmentId,duration:f.workDuration,distance:mode[2]==='hold'?'':f.workDistance});if(n<rounds-1){const rest={segmentId:uid('segment'),kind:'rest',label:'Rest '+(n+1),targetDurationMs:restMs,note:''};e.segments.push(rest);f.segments.push({segmentId:rest.segmentId,duration:f.restDuration,distance:''});}}
      changed();renderEditor();
    }catch(err){error(err.message);}
  }
  function segmentTarget(row){return [row.targetDurationMs!==null?duration(row.targetDurationMs):null,row.kind==='work'&&row.targetDistanceMm!==null?distance(row.targetDistanceMm):null].filter(Boolean).join(' · ');}
  function sequenceStrip(segments,currentId=null,records=[]){return '<ol class="interval-strip" aria-label="Ordered work and rest">'+segments.map((x,i)=>{const recorded=records.find(r=>r.segmentId===x.segmentId),actual=recorded?.actual;return '<li class="is-'+x.kind+(currentId===x.segmentId?' is-current':'')+(recorded?' is-observed':'')+'" '+(currentId===x.segmentId?'aria-current="step"':'')+'><small>'+String(i+1).padStart(2,'0')+' · '+(recorded?esc(recorded.status):esc(x.kind))+'</small><strong>'+esc(x.label)+'</strong><span>Target: '+esc(segmentTarget(x))+'</span>'+(actual?'<span>Actual: '+esc(duration(actual.durationMs))+' · '+esc(actual.durationSource)+(actual.distanceMm!==null?'<br>'+esc(distance(actual.distanceMm))+' · '+esc(actual.distanceSource):'')+'</span>':'')+'</li>';}).join('')+'</ol>';}
  function sequenceEditor(e,f){
    const report=ctx().workspace.domains.athletics.restrictions.find(x=>x.id===e.restrictionVersionId);return '<p class="conditioning-help">Build a repeated work and rest sequence. Each interval will guide you to the next action.</p>'+input('title','Session name',e.title,'maxlength="120" required')+'<div class="conditioning-form-grid">'+input('date','Date',e.date,'type="date" required')+input('location','Location / setting',e.location,'maxlength="80" required')+'</div><fieldset class="interval-repeat-builder"><legend>Work, rest, repeat</legend>'+select('repeatActivity','Work activity',f.activity,modes.map(x=>[x[0],x[1]]))+'<div class="conditioning-form-grid">'+input('workDuration','Work, seconds',f.workDuration,'type="number" min="0" step="any" inputmode="decimal"')+input('workDistance','Work distance, metres, optional',f.workDistance,'type="number" min="0" step="any" inputmode="decimal"')+input('restDuration','Rest between rounds, seconds',f.restDuration,'type="number" min="0" step="any" inputmode="decimal"')+input('rounds','Rounds',f.rounds,'type="number" min="1" max="50" step="1" inputmode="numeric"')+'</div>'+button('build-repeat',e.segments.length?'Replace sequence with these rounds':'Build this sequence','','button primary')+'<p class="conditioning-help">Rest is added between rounds. Targets stay blank until you enter them.</p></fieldset>'+(e.segments.length?sequenceStrip(e.segments)+'<div class="interval-edit-list">'+e.segments.map((x,i)=>{const form=f.segments.find(y=>y.segmentId===x.segmentId),eqs=equipment(),old=ctx().workspace.domains.athletics.equipment.find(q=>q.id===x.equipmentVersionId);if(old&&!eqs.some(q=>q.id===old.id))eqs.push(old);return '<details class="interval-edit"><summary><span>'+String(i+1).padStart(2,'0')+'</span> '+esc(x.label)+' <small>'+esc(segmentTarget(x))+'</small></summary>'+input('segmentLabel_'+x.segmentId,'Label',x.label,'maxlength="80" required')+'<div class="conditioning-form-grid">'+input('segmentDuration_'+x.segmentId,'Target, seconds',form?.duration||'','type="number" min="0" step="any" inputmode="decimal"')+(x.kind==='work'&&x.type==='locomotion'?input('segmentDistance_'+x.segmentId,'Target distance, metres',form?.distance||'','type="number" min="0" step="any" inputmode="decimal"'):'')+'</div>'+(x.kind==='work'?input('segmentVariant_'+x.segmentId,'Movement variant',x.variant,'maxlength="80" required')+'<div class="conditioning-form-grid">'+select('segmentPhase_'+x.segmentId,'Purpose',x.phase,[['warmup','Warm-up'],['work','Work'],['cooldown','Cool-down']])+select('segmentEquipment_'+x.segmentId,'Equipment',x.equipmentVersionId||'',[['','No equipment / outdoors'],...eqs.map(q=>[q.id,q.value.name+' · '+q.value.location])])+(x.activity==='carry'?input('segmentLoad_'+x.segmentId,'External load, kg',x.load??'','type="number" min="0" step="any" inputmode="decimal" required'):'')+'</div>'+input('segmentSurface_'+x.segmentId,'Surface / conditions, optional',x.surface,'maxlength="80"')+button('apply-segment','Use these settings for matching work intervals','data-segment="'+esc(x.segmentId)+'"','text-button'):'')+textarea('segmentNote_'+x.segmentId,'Note, optional',x.note)+'</details>';}).join('')+'</div>':'')+'<div class="conditioning-report"><strong>Current report attached</strong><p>'+esc(report?.value.note||'No movement patterns marked to avoid in the saved report.')+'</p>'+(latestReport()?.id!==e.restrictionVersionId?button('current-report','Use my current report','','text-button'):'')+'</div><details><summary>Time zone and development focus</summary>'+input('timeZone','Time zone',e.timeZone,'maxlength="100" required')+checks('focus',e.focus,capabilities)+textarea('note','Session notes, optional',e.note)+'</details>';
  }
  function renderSequenceActive(s){
    watchClock(s);const segments=s.prescription.value.segments,row=s.currentSegment,next=row?segments[s.segmentIndex+1]:null,observed=s.segmentActuals||[],elapsed=service().elapsed(s,stamp());return '<section class="conditioning-active interval-active" aria-label="Guided interval session"><div class="conditioning-active-top"><span class="conditioning-live '+(s.status==='running'?'is-running':'')+'">'+esc(s.status==='ready'?'Ready to finish':s.status==='running'?'In progress':'Paused')+'</span><span>'+observed.length+' of '+segments.length+' intervals recorded</span></div><h2>'+esc(s.prescription.value.title)+'</h2>'+sequenceStrip(segments,row?.segmentId,observed)+(row?'<div class="interval-current"><div class="eyebrow">Now · '+esc(row.kind)+'</div><h3>'+esc(row.label)+'</h3><div class="conditioning-stopwatch"><strong id="conditioningTimer" aria-live="off">'+esc(timerText(elapsed.elapsedMs))+'</strong><span>'+(row.kind==='rest'?'Recorded rest':'Current work')+' · pauses excluded</span></div><div class="conditioning-target"><small>Target</small><strong>'+esc(segmentTarget(row))+'</strong></div>'+(next?'<p class="interval-next">Next <strong>'+esc(next.label)+'</strong><span>'+esc(segmentTarget(next))+'</span></p>':'<p class="interval-next">Last interval. Review the session after this.</p>')+'<p id="conditioningClockHint" class="conditioning-help">'+(elapsed.timingIssues?.length?'Timing needs checking. Enter or estimate this interval before saving.':'The timer is an aid. Nothing advances until you choose the next action.')+'</p><div class="conditioning-active-controls">'+button(s.status==='running'?'pause':'resume',s.status==='running'?'Pause':'Start '+esc(row.kind),'data-session="'+esc(s.sessionId)+'"','button ghost')+button('segment-finish','Finish '+esc(row.kind),'data-session="'+esc(s.sessionId)+'"','button primary')+'</div><div class="interval-secondary">'+button('segment-skip','Skip this interval','data-session="'+esc(s.sessionId)+'"','text-button')+button('sequence-finish','Stop early','data-session="'+esc(s.sessionId)+'"','text-button')+'</div></div>':'<div class="interval-ready"><h3>Review what you did.</h3><p class="conditioning-help">Work and rest actuals stay separate. Skipped intervals do not become performed work.</p>'+button('sequence-finish','Finish this session','data-session="'+esc(s.sessionId)+'"','button primary')+'</div>')+(observed.length?'<details class="interval-completed"><summary>Recorded intervals · '+observed.length+'</summary>'+observed.map(x=>'<div><span>'+esc(segments.find(q=>q.segmentId===x.segmentId)?.label||x.segmentId)+' · '+esc(x.status)+'</span><strong>'+esc(x.actual?duration(x.actual.durationMs):'No work recorded')+'</strong>'+(x.actual?button('correct-segment','Correct','data-session="'+esc(s.sessionId)+'" data-segment="'+esc(x.segmentId)+'"','text-button'):'')+'</div>').join('')+'</details>':'')+'</section>';
  }
  function emptyActual(){return {durationMs:null,durationSource:'unknown',distanceMm:null,distanceSource:'unknown',effort:'unknown',discomfort:'',note:''};}
  function segmentDraft(sessionId,kind='advance',segmentId=null){
    const s=current(sessionId).session;if(!s?.sequence)return;const row=segmentId?s.prescription.value.segments.find(x=>x.segmentId===segmentId):s.currentSegment,previous=(s.segmentActuals||[]).find(x=>x.segmentId===row?.segmentId);if(!row||kind==='correct-segment'&&!previous?.actual)return api.toast('Choose an interval with a recorded actual.');const actual=kind==='correct-segment'?copy(previous.actual):{...emptyActual(),durationSource:'timer'};
    const entity={sessionId,segmentId:row.segmentId,outcome:previous?.status==='partial'?'partial':'complete',actual,timingConfirmed:false,...(kind==='advance'?{nextState:'running'}:{note:''})};keep(kind,entity,s.latestVersionId,{duration:decimal(actual.durationMs,1000),distance:decimal(actual.distanceMm,1000)});renderEditor();
  }
  async function correctSegment(sessionId,segmentId){if(busy||!available())return;const s=current(sessionId).session;if(s?.status==='running')await direct('pause',sessionId,()=>segmentDraft(sessionId,'correct-segment',segmentId));else segmentDraft(sessionId,'correct-segment',segmentId);}
  async function finishSegment(sessionId){if(!available()||busy)return;const s=current(sessionId).session;if(!s?.currentSegment)return;if(s.status==='running')await direct('pause',sessionId,()=>segmentDraft(sessionId));else segmentDraft(sessionId);}
  function segmentEditor(e,f,kind){
    const s=current(e.sessionId).session,row=s?.prescription.value.segments.find(x=>x.segmentId===e.segmentId),prior=s?.segmentActuals?.find(x=>x.segmentId===e.segmentId);if(!s||!row)return '<p class="conditioning-warning">The exact interval could not be found.</p>';const hold=row.kind==='rest'||row.type==='hold',observed=service().elapsed(s,stamp()),original=s.history.find(x=>x.operation==='advance'&&x.value.segmentId===e.segmentId)?.actual?.actual,next=s.prescription.value.segments[s.prescription.value.segments.findIndex(x=>x.segmentId===row.segmentId)+1];return '<div class="conditioning-target"><small>'+esc(row.kind)+' target</small><strong>'+esc(segmentTarget(row))+'</strong><span>'+esc(row.label)+'</span></div>'+select('outcome','What happened?',e.outcome,[['complete','Finished this interval'],['partial','Stopped before completing it']])+select('durationSource','Actual time',e.actual.durationSource,[...(kind!=='correct-segment'||original?.durationSource==='timer'?[['timer','Use the saved interval timer']]:[]),['entered','Enter measured time'],['estimated','Enter my estimate'],['unknown','Time not known']])+(e.actual.durationSource==='timer'?'<div class="conditioning-timer-review"><strong>'+esc(duration(kind==='correct-segment'?original?.durationMs:observed.elapsedMs))+'</strong><p class="conditioning-help">Saving confirms this time reflects this '+esc(row.kind)+' interval, excluding pauses. Change the source if it does not match.</p></div>':['entered','estimated'].includes(e.actual.durationSource)?input('duration','Actual seconds',f.duration,'type="number" min="0" step="any" inputmode="decimal" required'):'')+(!hold?'<div class="conditioning-form-grid">'+input('distance','Actual metres, optional',f.distance,'type="number" min="0" step="any" inputmode="decimal"')+select('distanceSource','Distance source',e.actual.distanceSource,[['unknown','Not known'],['measured','Measured'],['entered','Entered from a record'],['estimated','Estimated']])+'</div>':'')+(kind==='advance'&&next?select('nextState','After saving this interval',e.nextState,[['running','Start '+next.label],['paused','Keep '+next.label+' paused']]):'')+'<details><summary>Effort and notes</summary>'+select('effort','How hard did it feel?',e.actual.effort,[['unknown','Not recorded'],['easy','Easy'],['moderate','Moderate'],['hard','Hard']])+textarea('discomfort','Discomfort, optional',e.actual.discomfort)+textarea('actualNote','What happened, optional',e.actual.note)+(kind==='correct-segment'?textarea('correctionNote','Reason for correction, optional',e.note):'')+'</details>'+(prior&&kind==='correct-segment'?'<p class="conditioning-help">The earlier interval record stays in history. Other intervals are unchanged.</p>':'');
  }
  function sequenceEndDraft(sessionId){const s=current(sessionId).session;if(!s?.sequence)return;const all=s.status==='ready'&&s.segmentActuals.every(x=>x.status==='complete');keep('finish-sequence',{sessionId,outcome:all?'complete':'incomplete',note:''},s.latestVersionId);renderEditor();}
  async function endSequence(sessionId){if(!available()||busy)return;const s=current(sessionId).session;if(!s?.sequence)return;if(s.status==='running')await direct('pause',sessionId,()=>sequenceEndDraft(sessionId));else sequenceEndDraft(sessionId);}
  function sequenceFinishEditor(e){const s=current(e.sessionId).session;return '<h3>'+esc(s?.prescription.value.title)+'</h3><p class="conditioning-help">Only recorded intervals count as actual work or rest. An unfinished current interval stays unrecorded; later intervals stay unattempted.</p>'+select('outcome','Session outcome',e.outcome,[['incomplete','Ended early / incomplete'],['complete','All intervals completed']])+textarea('sessionNote','What should you remember?',e.note)+(s?.currentSegment?'<p class="conditioning-warning">'+esc(s.currentSegment.label)+' has no saved actual yet. Close this draft and finish that interval first if you want to record its progress.</p>':'');}
  function observation(kind,rootId){
    if(!available())return;const rows=service().currentObservations(ctx().workspace).observations,old=rows.find(x=>x.rootId===rootId),zone=old?.value.timeZone||Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC',value=old?copy(old.value):{rootId:uid('activity-note'),kind,date:localDay(zone),timeZone:zone,title:'',protocol:'',context:'',criteria:'',result:'unknown',attempts:null,successes:null,focus:[kind==='skill'?'coordination':'conditioning'],equipmentVersionId:null,load:null,convention:null,actual:emptyActual()};keep(old?'correct-observation':'observe',value,old?.versionId||null,{duration:decimal(value.actual.durationMs,value.kind==='skill'?1000:60000),distance:decimal(value.actual.distanceMm,1000000)});renderEditor();
  }
  function observationEditor(e,f,kind){return '<p class="conditioning-help">Record what happened. This is a factual note for your training history, with no session or target invented.</p>'+input('title',e.kind==='skill'?'What did you practise?':'What sport or activity did you do?',e.title,'maxlength="120" required')+'<div class="conditioning-form-grid">'+input('date','Date',e.date,'type="date" required '+(kind==='correct-observation'?'readonly':''))+input('context','Setting / context, optional',e.context,'maxlength="200"')+'</div>'+(e.kind==='skill'?input('protocol','Attempt or method',e.protocol,'maxlength="500" placeholder="Name the technique and conditions" required')+textarea('criteria','What counts as success?',e.criteria)+select('result','Result against those criteria',e.result,[['unknown','Not assessed'],['met','Met the criteria'],['partial','Partly met'],['not-met','Not yet met']])+'<div class="conditioning-form-grid">'+input('attempts','Attempts, optional',e.attempts??'','type="number" min="0" step="1" inputmode="numeric"')+input('successes','Successful attempts, optional',e.successes??'','type="number" min="0" step="1" inputmode="numeric"')+'</div>':'')+select('durationSource','Duration source',e.actual.durationSource,[['unknown','Not recorded'],['entered','Measured duration'],['estimated','My estimate']])+(['entered','estimated'].includes(e.actual.durationSource)?input('duration',e.kind==='skill'?'Actual seconds':'Actual minutes',f.duration,'type="number" min="0" step="any" inputmode="decimal" required'):'')+select('effort','How hard did it feel?',e.actual.effort,[['unknown','Not recorded'],['easy','Easy'],['moderate','Moderate'],['hard','Hard']])+textarea('actualNote','What happened?',e.actual.note)+'<details><summary>More context</summary>'+input('timeZone','Time zone',e.timeZone,'maxlength="100" required '+(kind==='correct-observation'?'readonly':''))+'<div class="conditioning-form-grid">'+input('distance','Actual distance, km, optional',f.distance,'type="number" min="0" step="any" inputmode="decimal"')+select('distanceSource','Distance source',e.actual.distanceSource,[['unknown','Not recorded'],['measured','Measured'],['entered','Entered from a record'],['estimated','Estimated']])+'</div>'+checks('focus',e.focus,capabilities)+textarea('discomfort','Discomfort, optional',e.actual.discomfort)+'</details>';}
  function syncExtended(form,f){
    const d=draft.data,e=d.entity;for(const key of ['duration','distance'])if(f[key]!==undefined)d.form[key]=f[key];
    if(draft.kind==='prescribe-sequence'){
      for(const key of ['title','date','location','timeZone','note'])if(f[key]!==undefined)e[key]=f[key];e.focus=[...form.querySelectorAll('[data-conditioning-focus]:checked')].map(x=>x.dataset.conditioningFocus);for(const [field,key] of [['repeatActivity','activity'],['workDuration','workDuration'],['workDistance','workDistance'],['restDuration','restDuration'],['rounds','rounds']])if(f[field]!==undefined)d.form[key]=f[field];
      for(const row of e.segments){const id=row.segmentId,values=d.form.segments.find(x=>x.segmentId===id);for(const [field,key] of [['segmentLabel_','label'],['segmentNote_','note'],['segmentVariant_','variant'],['segmentPhase_','phase'],['segmentSurface_','surface']])if(f[field+id]!==undefined)row[key]=f[field+id];if(f['segmentDuration_'+id]!==undefined)values.duration=f['segmentDuration_'+id];if(f['segmentDistance_'+id]!==undefined)values.distance=f['segmentDistance_'+id];if(row.kind==='work'&&f['segmentEquipment_'+id]!==undefined){row.equipmentVersionId=f['segmentEquipment_'+id]||null;if(row.activity==='carry'){row.load=f['segmentLoad_'+id]??row.load;row.convention=ctx().workspace.domains.athletics.equipment.find(x=>x.id===row.equipmentVersionId)?.value.convention||null;}}}
    }else if(draft.kind==='finish-sequence'){e.outcome=f.outcome??e.outcome;e.note=f.sessionNote??e.note;}
    else{
      for(const key of ['durationSource','distanceSource','effort','discomfort'])if(f[key]!==undefined)e.actual[key]=f[key];e.actual.note=f.actualNote??e.actual.note;
      if(['advance','correct-segment'].includes(draft.kind)){e.outcome=f.outcome??e.outcome;if(draft.kind==='advance')e.nextState=f.nextState??e.nextState;else e.note=f.correctionNote??e.note;e.timingConfirmed=e.actual.durationSource==='timer';}
      else{for(const key of ['title','date','timeZone','context','protocol','criteria','result'])if(f[key]!==undefined)e[key]=f[key];for(const key of ['attempts','successes'])if(f[key]!==undefined)e[key]=f[key]===''?null:f[key];e.focus=[...form.querySelectorAll('[data-conditioning-focus]:checked')].map(x=>x.dataset.conditioningFocus);}
    }
  }
  function normalizedExtended(){
    const e=copy(draft.data.entity),f=draft.data.form;if(draft.kind==='prescribe-sequence'){for(const row of e.segments){const values=f.segments.find(x=>x.segmentId===row.segmentId);row.targetDurationMs=editedUnits(values.duration,1000,row.targetDurationMs);if(row.kind==='work'){row.targetDistanceMm=row.type==='hold'?null:editedUnits(values.distance,1000,row.targetDistanceMm);if(row.activity==='carry')row.load=row.load===''?NaN:Number(row.load);}}return e;}
    if(draft.kind==='finish-sequence')return e;const isSegment=['advance','correct-segment'].includes(draft.kind),row=isSegment?current(e.sessionId).session?.prescription.value.segments.find(x=>x.segmentId===e.segmentId):null,hold=isSegment&&(row.kind==='rest'||row.type==='hold'),scale=isSegment||e.kind==='skill'?1000:60000;e.actual.durationMs=['entered','estimated'].includes(e.actual.durationSource)?editedUnits(f.duration,scale,e.actual.durationMs):null;e.actual.distanceMm=hold?null:editedUnits(f.distance,isSegment?1000:1000000,e.actual.distanceMm);if(hold)e.actual.distanceSource='unknown';if(isSegment)e.timingConfirmed=e.actual.durationSource==='timer';else for(const key of ['attempts','successes'])e[key]=e[key]===null?null:Number(e[key]);return e;
  }
  function renderExtendedReview(){
    const c=review.command,e=c.entity;let body='',label='Save actual record';
    if(c.operation==='prescribe-sequence'){body='<h3>'+esc(e.title)+'</h3><p class="conditioning-context">'+esc(labelDate(e.date))+' · '+esc(e.location)+'</p>'+sequenceStrip(e.segments)+'<p class="conditioning-help">'+esc(planned(e))+'. Actual work and rest are recorded one interval at a time.</p>';label='Approve interval session';}
    else if(['advance','correct-segment','skip'].includes(c.operation)){const s=current(e.sessionId).session,row=s.prescription.value.segments.find(x=>x.segmentId===e.segmentId),next=s.prescription.value.segments[s.prescription.value.segments.findIndex(x=>x.segmentId===e.segmentId)+1],actual=review.record?.actual?.actual||review.record?.actual;body='<h3>'+esc(row.label)+'</h3>'+(c.operation==='skip'?'<p class="conditioning-warning">Skip this interval without recording performed work or rest.</p>':'<div class="conditioning-comparison"><div><small>Target</small><strong>'+esc(segmentTarget(row))+'</strong></div><div><small>'+esc(e.outcome==='partial'?'Actual · partial':'Actual')+'</small><strong>'+esc(duration(actual?.durationMs??e.actual.durationMs))+'</strong><span>'+esc(distance(actual?.distanceMm??e.actual.distanceMm))+'</span></div></div><p class="conditioning-help">Time source: '+esc(e.actual.durationSource)+'. Distance source: '+esc(e.actual.distanceSource)+'.</p>')+(c.operation!=='correct-segment'&&next?'<p class="interval-next">Next <strong>'+esc(next.label)+'</strong><span>'+(e.nextState==='running'?'Timer starts when you save.':'Remains paused until you start it.')+'</span></p>':'');label=c.operation==='skip'?'Skip'+(next&&e.nextState==='running'?' and start '+next.label:''):c.operation==='correct-segment'?'Save interval correction':next&&e.nextState==='running'?'Save actual and start '+next.label:'Save actual';}
    else if(c.operation==='finish-sequence'){const s=current(e.sessionId).session;body='<h3>'+esc(s.prescription.value.title)+'</h3><p class="conditioning-help">'+esc(e.outcome==='complete'?'All intervals recorded as complete.':'Incomplete session. Unrecorded or unattempted intervals retain those labels.')+'</p>'+sequenceStrip(s.prescription.value.segments,null,s.segmentActuals)+'<p class="conditioning-note">'+esc(e.note)+'</p>';label='Finish session';}
    else{body='<h3>'+esc(e.title)+'</h3><p class="conditioning-context">'+esc(labelDate(e.date))+' · '+esc(e.kind==='skill'?'Skill practice':'Other sport')+'</p>'+(e.kind==='skill'?'<p class="conditioning-help">'+esc(e.protocol)+'<br>'+esc(e.criteria)+'<br>Result: '+esc(e.result)+(e.attempts!==null?' · '+esc(e.attempts)+' attempts':'')+(e.successes!==null?' · '+esc(e.successes)+' successful':'')+'</p>':'')+'<div class="conditioning-target"><small>Actual · '+esc(e.actual.durationSource)+'</small><strong>'+esc(duration(e.actual.durationMs))+'</strong><span>'+esc(distance(e.actual.distanceMm))+'</span></div><p class="conditioning-note">'+esc(e.actual.note)+'</p>';label=c.operation==='correct-observation'?'Save correction':'Save activity note';}
    show('Review this next step.','<div class="conditioning-review"><div class="eyebrow">Review · nothing committed</div>'+body+errorHtml()+'<div class="dialog-footer">'+button(draft?'resume-draft':'close','Back')+button('commit',esc(label),'','button primary')+'</div></div>');
  }
  function renderProgress(){if(!api)return '';return contextual(()=>renderSteadyProgress()+renderSequenceHistory()+renderObservations());}
  function renderSequenceHistory(){const rows=service().currentActuals(ctx().workspace).actuals.filter(x=>x.prescription.value.type==='sequence').slice().reverse();if(!rows.length)return '';return '<section class="conditioning-progress"><div class="eyebrow">Interval history</div><h3>Work and recovery, separately.</h3>'+rows.slice(0,sequenceHistoryLimit).map(x=>button('actual','<span>'+esc(x.prescription.value.title)+'</span><small>'+esc(labelDate(x.date))+' · '+esc(x.outcome)+' · work '+esc(duration(x.actual.summary.workDurationMs))+' · rest '+esc(duration(x.actual.summary.restDurationMs))+'</small>','data-session="'+esc(x.sessionId)+'"','conditioning-actual-row')).join('')+(rows.length>sequenceHistoryLimit?button('more-sequence-history','Show earlier sessions','','text-button'):'')+'</section>';}
